\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Color Theme (Institutional Blues & Warm Accent) ──
\definecolor{primary}{HTML}{0B3D91}     % Deep Institutional Blue
\definecolor{secondary}{HTML}{0E7490}   % Professional Teal
\definecolor{accent}{HTML}{D97706}      % Warm Amber (Gold)
\definecolor{bgposter}{HTML}{F8FAFC}    % Clean Slate 50
\definecolor{redbg}{HTML}{FFFBEB}       % Amber tint for accent cards
\definecolor{bluebg}{HTML}{F0F9FF}      % Sky blue tint for teal cards
\definecolor{darkbg}{HTML}{F1F5F9}      % Slate tint for primary cards
\definecolor{redtitlebg}{HTML}{FEF3C7}  
\definecolor{bluetitlebg}{HTML}{E0F2FE} 
\definecolor{darktitlebg}{HTML}{E2E8F0} 
\definecolor{textdark}{HTML}{0F172A}
\definecolor{textgray}{HTML}{334155}
\definecolor{stathighlight}{HTML}{FFFBEB}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=10pt, parsep=2pt, topsep=6pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=10pt, parsep=2pt, topsep=6pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Card styles (left accent stripe design) ──
\tcbset{
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={4pt}{0pt}{accent},
    left=16pt, right=16pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=redtitlebg,
    toptitle=10pt, bottomtitle=10pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.15},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={4pt}{0pt}{secondary},
    left=16pt, right=16pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=bluetitlebg,
    toptitle=10pt, bottomtitle=10pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={4pt}{0pt}{primary},
    left=16pt, right=16pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=darktitlebg,
    toptitle=10pt, bottomtitle=10pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!15!white,
    borderline west={5pt}{0pt}{primary},
    left=16pt, right=16pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=10pt, bottomtitle=10pt,
    valign=top, drop shadow={opacity=0.2},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=32pt, right=32pt, top=20pt, bottom=16pt,
  halign=center, valign=center,
  drop shadow={opacity=0.25}
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{72}{86}\selectfont\bfseries Global Economic Prospects}\\[16pt]
  {\fontsize{42}{52}\selectfont\bfseries Resilience Amid Uncertainty}\\[20pt]
  {\fontsize{28}{36}\selectfont\color{white!85} World Bank Group \ \ |\ \ Policy \& Economics Report \ \ |\ \ 2025}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=white, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=12pt, bottom=12pt,
  valign=center, borderline south={2pt}{0pt}{primary!25},
]{name=stats, column=1, span=2, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.28\linewidth}\centering
